<?php
require_once __DIR__ . '/../includes/bootstrap.php'; require_role(['admin','teacher']);
$error=''; $success='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 verify_csrf(); $action=$_POST['action']??'';
 if ($action==='save') {
  $name=trim($_POST['full_name']??''); $class=trim($_POST['class_name']??''); $gender=$_POST['gender']??''; $phone=trim($_POST['parent_phone']??''); $dob=$_POST['date_of_birth']?:null; $sid=trim($_POST['student_code']??'');
  if ($name==='' || $class==='') $error='Magaca ardayga iyo fasalka waa qasab.';
  else {
   if ($sid==='') $sid='STD-'.date('y').'-'.strtoupper(bin2hex(random_bytes(3)));
   try { $s=db()->prepare('INSERT INTO students(student_code,full_name,class_name,gender,date_of_birth,parent_phone,status) VALUES(?,?,?,?,?,?,?)'); $s->execute([$sid,$name,$class,$gender?:null,$dob,$phone?:null,'active']); log_activity('create','student',(int)db()->lastInsertId(),'Diiwaangelin arday'); $success='Ardayga si guul leh ayaa loo diiwaangeliyey.'; }
   catch(PDOException $e) { $error=$e->getCode()==='23000'?'Student ID-kan hore ayuu u jiraa.':'Xogta lama kaydin. Hubi database-ka.'; }
  }
 }
 if ($action==='archive' && current_user()['role']==='admin') { $id=(int)($_POST['id']??0); db()->prepare('UPDATE students SET deleted_at=NOW(), status="inactive" WHERE id=?')->execute([$id]); log_activity('archive','student',$id,'Arday si soft-delete ah loo qariyey'); $success='Ardayga waa la qariyey; xogtiisa database-ka way sii jirtaa.'; }
}
$search=trim($_GET['q']??''); $stmt=db()->prepare('SELECT * FROM students WHERE deleted_at IS NULL AND (full_name LIKE ? OR student_code LIKE ? OR class_name LIKE ?) ORDER BY created_at DESC LIMIT 200'); $like='%'.$search.'%'; $stmt->execute([$like,$like,$like]); $students=$stmt->fetchAll();
$pageTitle='Maamulka Ardayda'; require __DIR__.'/../includes/header.php';
?><div class="page-toolbar"><div><h1>Ardayda</h1><p class="muted">Diiwaangelinta iyo raadinta ardayda.</p></div><button class="btn primary" type="button" onclick="document.getElementById('studentForm').classList.toggle('hidden')">+ Diiwaangeli arday</button></div>
<?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?=e($success)?></div><?php endif; ?>
<section class="panel form-panel hidden" id="studentForm"><div class="panel-heading"><h3>Diiwaangelinta arday cusub</h3></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><label>Magaca oo buuxa *<input name="full_name" required maxlength="150"></label><label>Student ID (ikhtiyaari)<input name="student_code" maxlength="40" placeholder="Si otomaatig ah ayaa loo samaynayaa"></label><label>Fasalka *<select name="class_name" required><option value="">Dooro fasal</option><?php for($i=1;$i<=12;$i++): ?><option>Grade <?=$i?></option><?php endfor; ?></select></label><label>Jinsiga<select name="gender"><option value="">Dooro</option><option value="male">Lab</option><option value="female">Dheddig</option><option value="other">Kale</option></select></label><label>Taariikhda dhalashada<input type="date" name="date_of_birth"></label><label>Telefoonka waalidka<input name="parent_phone" maxlength="40"></label><div class="form-actions"><button class="btn primary">Kaydi ardayga</button><button class="btn secondary" type="button" onclick="document.getElementById('studentForm').classList.add('hidden')">Jooji</button></div></form></section>
<section class="panel"><div class="panel-heading"><div><h3>Diiwaanka ardayda</h3><p class="muted"><?=count($students)?> natiijo (ugu badnaan 200)</p></div><form class="search-form" method="get"><input name="q" value="<?=e($search)?>" placeholder="Raadi magac, ID, fasal"><button class="btn secondary">Raadi</button></form></div><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Magaca ardayga</th><th>Fasalka</th><th>Jinsiga</th><th>Xaaladda</th><?php if(current_user()['role']==='admin'): ?><th>Ficil</th><?php endif; ?></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><span class="code-pill"><?=e($s['student_code'])?></span></td><td><b><?=e($s['full_name'])?></b></td><td><?=e($s['class_name'])?></td><td><?=e($s['gender']??'—')?></td><td><span class="status active"><?=e($s['status'])?></span></td><?php if(current_user()['role']==='admin'): ?><td><form method="post" onsubmit="return confirm('Ma hubtaa inaad ardaygan qariso? Xogtu ma tirmayso.')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="text-danger">Qari</button></form></td><?php endif; ?></tr><?php endforeach; if(!$students): ?><tr><td colspan="6" class="empty-state">Arday lama helin. Diiwaangeli ardayga koowaad.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
